import random
r = random.Random(200)
ops = []
nv = 1
for _ in range(40):
    x = r.random(); v = r.randint(-1, nv + 1) if r.random() < 0.05 else max(0, nv - 1 - int(r.expovariate(0.3)))
    if x < 0.35:
        ops.append(('set', v, r.randint(-5, 5), r.randint(-100, 100)))
        nv += 1 if 0 <= v < nv else 0
    elif x < 0.5: ops.append(('del', v, r.randint(-5, 5)))
    elif x < 0.62: ops.append(('get', v, r.randint(-5, 5)))
    elif x < 0.74:
        a = r.randint(-5, 5); ops.append(('count', v, a, a + r.randint(-3, 5)))
    elif x < 0.86:
        a = r.randint(-5, 5); ops.append(('sum', v, a, a + r.randint(-3, 5)))
    else: ops.append(('kth', v, r.randint(0, 5)))
result = sol.run_ops(ops)

