import random
r = random.Random(31)
ops = []
nv = 1
for i in range(150000):
    x = r.random() if i >= 40000 else 0.0
    v = (nv - 1) if i >= 40000 else nv - 1
    if x < 0.3:
        ops.append(('set', v, r.randint(-1000000, 1000000), r.randint(-10**6, 10**6))); nv += 1
    elif x < 0.7: ops.append(('del', v, r.randint(-1000000, 1000000)))
    elif x < 0.80: ops.append(('get', v, r.randint(-1000000, 1000000)))
    elif x < 0.87:
        a = r.randint(-1000000, 1000000); ops.append(('count', v, a, a + r.randint(0, 1000000)))
    elif x < 0.94:
        a = r.randint(-1000000, 1000000); ops.append(('sum', v, a, a + r.randint(0, 1000000)))
    else: ops.append(('kth', v, r.randint(1, 40000)))
out = sol.run_ops(ops)
result = (len(out), sum(x for x in out if type(x) is int) % 1000000007, out.count(None), out.count('BADVER'), out.count('NOKEY'), out[::2503])

